fixture={"data":[{"id":101,"name":"Ada","active":True,"total":12.5,"team":{"name":"Platform"}},{"id":102,"name":"Lin","active":False,"total":8,"team":None},{"id":103,"name":"Sam","active":True,"total":20,"team":{"name":"API"}}],"meta":{"page":1,"total":3}}
Path('tools/resources-editorial/response.json').write_text(json.dumps(fixture,indent=2),encoding='utf-8')
save('3069',[
p('jq is a command-line JSON processor. Use it to select response fields, filter arrays and reshape JSON without writing a separate script. A jq filter reads a JSON value and produces one or more output values; a pipe passes each output into the next filter.'),p('The examples below use one small response so you can compare the filters directly. Install jq from its <a href="https://jqlang.org/download/">official download page</a> and check <em>jq --version</em>. The commands use Bash-style quoting. In Windows PowerShell, call the jq executable directly and use a filter file if embedded quotes become difficult.'),
h('1. Save a Small Response to Practice With'),p('Save this JSON as <em>response.json</em>. The root is an object, <em>data</em> is an array, and one user has no team. Those differences matter when choosing a filter:'),c(json.dumps(fixture,indent=2),'json'),p('Pretty-print the document or validate that it parses with the identity filter, a dot that returns its input:'),c("jq '.' response.json",'bash'),
h('2. Select Fields and Nested Values'),p('A field lookup starts from the value currently flowing through the filter. Array indexing starts at zero. Raw output removes JSON quotes around strings; it does not convert arbitrary objects into plain text.'),t(['Goal','Command','Result'],[['First user name',"<code>jq -r '.data[0].name' response.json</code>",'Ada'],['Total records',"<code>jq '.meta.total' response.json</code>",'3'],['Names, one per line',"<code>jq -r '.data[].name' response.json</code>",'Ada, Lin and Sam on separate lines'],['A key containing a hyphen',"<code>jq '.&quot;request-id&quot;' error.json</code>",'Value of that exact key']]),p('Use quoted key syntax when a field name contains punctuation. A missing field normally produces null. That is different from a malformed document, which causes a parse error.'),
h('3. Filter Arrays and Keep an Array'),p('The <em>[]</em> operator emits each array element separately. <em>select</em> keeps matching values. Brackets around the full filter collect those outputs back into one array:'),c("jq '[.data[] | select(.active == true) | .name]' response.json",'bash'),p('The result is <em>["Ada", "Sam"]</em>. Without the outer brackets, the filter emits two separate JSON strings. Use <em>map</em> when the input is already an array and you want another array:'),c("jq '.data | map(select(.total >= 10) | {id, total})' response.json",'bash'),p('Do not use truthiness alone to identify active users when the API can send strings such as "false". Compare the documented boolean value explicitly.'),
h('4. Reshape Objects and Handle Missing Values'),p('Construct an object by naming the fields you want. The alternative operator <em>//</em> supplies a fallback for null or false. It does not replace every empty string or zero:'),c("jq '.data | map({id, name, team: (.team.name // \"Unassigned\")})' response.json",'bash'),p('This keeps one output object per user and gives Lin the team label Unassigned. If false is a meaningful value, do not use <em>//</em> to distinguish it from a missing field; check field presence or null explicitly.'),
h('5. Sort, Count and Sum'),p('Sorting and aggregation operate on an array, so select <em>data</em> before applying them. Keep JSON numbers as numbers rather than sorting numeric strings lexically:'),c("jq '.data | sort_by(.total) | reverse' response.json\njq '.data | length' response.json\njq '[.data[].total] | add' response.json",'bash'),p('The count is 3 and the sum is 40.5. For empty collections, design a deliberate default such as <em>add // 0</em>. For money, follow the API\'s numeric representation instead of assuming floating-point arithmetic provides exact financial totals.'),
h('6. Produce CSV and Pass Variables Safely'),p('The <em>@csv</em> formatter expects an array representing one row. The following filter emits a header and one row per user. Raw output prevents a second layer of JSON quoting around each CSV line:'),c("jq -r '([\"id\",\"name\"], (.data[] | [.id, .name])) | @csv' response.json",'bash'),p('Pass external text with <em>--arg</em> rather than constructing jq source from shell input. Use <em>--argjson</em> for a value that should be parsed as JSON, such as a number:'),c("jq --arg wanted 'Ada' '.data[] | select(.name == $wanted)' response.json\njq --argjson minimum 10 '[.data[] | select(.total >= $minimum)]' response.json",'bash'),p('Shell variables and jq variables are separate. Single quotes preserve <em>$wanted</em> for jq instead of asking the shell to expand it.'),
h('7. Combine curl with jq'),p('For a quick read, pipe the response body into jq. Keep headers out of the JSON stream: <em>curl -i</em> mixes response headers with the body and causes a parse error.'),c("curl --fail-with-body --silent --show-error https://jsonplaceholder.typicode.com/users | jq -r '.[].name'",'bash'),p('For a script that must distinguish a failed HTTP request from bad JSON, save the body first and run jq only if curl succeeds:'),c("curl --fail-with-body --silent --show-error -o users.json https://jsonplaceholder.typicode.com/users && jq -r '.[].name' users.json",'bash'),p('In Bash pipelines, <em>set -o pipefail</em> also helps expose failures in earlier commands. A successful jq parse alone does not prove that the preceding HTTP call succeeded.'),
h('8. Common Errors and Script Checks'),p('Cannot index array with string usually means the root is an array but the filter expects an object. Cannot iterate over null often means a path is missing. Inspect the actual response before adding optional operators that hide a contract change.'),p('Use <em>-e</em> when a filter\'s result should decide script success. For a single boolean check, it returns success for true and failure for false or null:'),c("jq -e '.meta.total == 3' response.json",'bash'),p('For JSON Lines, jq reads multiple JSON values without needing one surrounding array. Use <em>-s</em> only when you intentionally want to collect all input values in memory. Large responses may need a streaming approach instead.'),
h('9. Conclusion'),p('Check the root shape first, then select, filter and reshape. Keep HTTP failure handling separate from JSON processing, and pass external values as arguments rather than generated filter text.'),h('10. References'),refs([('jq manual','https://jqlang.org/manual/'),('jq downloads','https://jqlang.org/download/'),('curl manual','https://curl.se/docs/manpage.html')])],
'jq Cheat Sheet for REST API Responses: Filters and Examples','Use jq to select fields, filter arrays, reshape JSON, create CSV and process curl responses. Includes a sample response and tested filters.','Practical jq examples for REST responses: nested fields, array filters, defaults, sorting, totals, CSV, variables and reliable curl pipelines.','jq cheat sheet')

save('3035',[
p('curl sends HTTP requests from a terminal and shows the server\'s response. This cheat sheet covers common REST API calls, file transfers, authentication and diagnostics. Use it to reproduce a request independently of a browser or SDK.'),p('Examples use Bash-style quotes and backslash continuations. On Windows PowerShell, use <em>curl.exe</em> to select curl rather than a shell alias, and put commands on one line or adapt the continuation syntax. Check <em>curl --version</em>; older installations may lack newer options such as <em>--json</em>.'),
h('1. GET Requests and Query Parameters'),p('A URL alone sends GET. Use <em>-i</em> to show response headers with the body, or <em>-v</em> when you need connection diagnostics. This public example reads one placeholder post:'),c('curl -i https://jsonplaceholder.typicode.com/posts/1','bash'),p('For query parameters, let curl encode their values. <em>--get</em> places data options in the query rather than sending a POST body:'),c('curl --get "https://api.example.com/products" \\\n  --data-urlencode "q=tea & coffee" \\\n  --data-urlencode "limit=10"','bash'),p('Quote URLs containing ampersands so the shell does not interpret them as job-control syntax. Replace api.example.com with the service you are testing.'),
h('2. POST JSON from a String or File'),p('<em>--json</em> supplies JSON-oriented Content-Type and Accept headers and sends the supplied data. It does not validate that the content is valid JSON:'),c('curl --json \'{"sku":"BOOK-7","quantity":2}\' https://api.example.com/orders\ncurl --json @order.json https://api.example.com/orders','bash'),p('For older curl versions, specify the content type and body explicitly. <em>--data-binary</em> preserves the bytes in a file:'),c('curl -H "Content-Type: application/json" \\\n  --data-binary @order.json https://api.example.com/orders','bash'),p('The data option selects POST unless another method is specified. A JSON field that says method: PUT does not change the HTTP method.'),
h('3. PUT, PATCH and DELETE'),p('Use <em>--request</em>, or its short form <em>-X</em>, for the intended method. The server\'s contract decides whether PUT replaces a representation and which PATCH format is supported:'),c('curl --request PUT --json @replacement.json https://api.example.com/products/7\ncurl --request PATCH -H "Content-Type: application/merge-patch+json" \\\n  --data-binary @patch.json https://api.example.com/products/7\ncurl --request DELETE https://api.example.com/products/7','bash'),p('These examples assume operations with those semantics; they do not make arbitrary endpoints support the methods. A successful DELETE can return 204 with no body, so an empty response is not necessarily an error.'),
h('4. Authentication and Headers'),p('Send the authentication format the API documents. Basic authentication sends credentials encoded for transport, not encrypted by that encoding, so use HTTPS. Omitting the password from <em>--user</em> lets curl prompt for it.'),c('curl --user demo https://api.example.com/profile\ncurl -H "Authorization: Bearer $API_TOKEN" https://api.example.com/profile\ncurl -H "X-API-Key: $API_KEY" https://api.example.com/profile','bash'),p('API_TOKEN and API_KEY are environment-variable placeholders. Environment variables keep examples reusable, but a shell-expanded secret can still appear in process arguments or diagnostics. Use your platform\'s secret-handling workflow, and redact verbose logs before sharing them.'),
h('5. Forms and File Uploads'),p('For simple form fields, use URL-encoded data. For file uploads, <em>-F</em> builds a multipart body and includes its boundary automatically:'),c('curl --data-urlencode "name=Ada Lovelace" https://api.example.com/profile\ncurl -F "file=@report.pdf" -F "category=monthly" https://api.example.com/uploads','bash'),p('Do not manually set a generic multipart Content-Type that omits the generated boundary. For an endpoint that accepts raw file bytes instead, use <em>--data-binary @report.pdf</em> and the documented media type. Multipart and raw uploads are different contracts.'),
h('6. Save the Body, Headers and Status Separately'),p('Keeping these outputs separate makes responses easier to inspect and avoids feeding HTTP headers to a JSON parser:'),c('curl --silent --show-error --fail-with-body \\\n  --dump-header headers.txt --output body.json \\\n  --write-out "HTTP %{http_code} in %{time_total}s\\n" \\\n  https://api.example.com/products/7','bash'),p('<em>--fail-with-body</em> normally makes HTTP 400-and-higher responses fail the curl command while retaining the body. Without a fail option, transferring an HTTP error response can still produce curl exit code 0. Inspect both the HTTP status and process result in automation.'),p('<em>-I</em> sends HEAD; it does not simply hide a GET body. Some services implement HEAD differently. To inspect a GET while discarding its body, use an output destination appropriate to your shell and retain the headers separately.'),
h('7. Redirects, Timeouts and Retries'),p('<em>--location</em> follows redirects. Be careful with a copied command containing a forced method: explicitly setting a method with -X can change what is reused during redirects. Inspect the redirect chain rather than assuming every hop preserves the original request semantics.'),c('curl --location --connect-timeout 3 --max-time 15 https://api.example.com/products\ncurl --retry 2 --retry-max-time 20 https://api.example.com/products','bash'),p('A connection timeout and a total deadline cover different periods. The retry example is for a read operation. Before retrying writes, use the service\'s idempotency mechanism or verify the outcome. A lost response does not prove the server did nothing. Avoid adding <em>--retry-all-errors</em> indiscriminately.'),
h('8. Debug the Request You Actually Sent'),p('Use <em>-v</em> to inspect request and response headers and connection details. An HTTP 401 suggests authentication trouble; 415 suggests an input-format mismatch; 413 suggests a size limit. Check the body for application details, and correlate the request identifier with server logs.'),p('Keep TLS certificate verification enabled. For an internal certificate authority, configure the trusted certificate with the documented CA options rather than copying <em>-k</em> into scripts. Never paste production credentials into public echo services.'),
h('9. Conclusion'),p('Start with the method, URL, headers and body, then separate response diagnostics from content. In scripts, check HTTP failures and process exit codes, and design retries around the operation\'s safety.'),h('10. References'),refs([('curl manual','https://curl.se/docs/manpage.html'),('Everything curl: HTTP requests','https://everything.curl.dev/http/requests/'),('HTTP methods','https://restfulapi.net/http-methods/'),('HTTP status codes','https://restfulapi.net/http-status-codes/')])],
'curl Cheat Sheet for REST APIs: JSON, Auth, Files and Status','Copy practical curl commands for REST APIs: POST JSON, PUT, PATCH, authentication, multipart uploads, response status, redirects and timeouts.','A curl reference for REST calls, JSON bodies, auth, file uploads, status codes and troubleshooting, with guidance on quoting, redirects and safe retries.','curl post json')

save('3047',[
p('A media type, often called a MIME type, tells an HTTP recipient how to interpret content. Set it in <em>Content-Type</em>, for example <em>application/json</em> for a JSON body. A filename extension alone does not describe the bytes sent over HTTP.'),p('This reference groups common API payload types, file types and form formats. The <a href="https://www.iana.org/assignments/media-types/">IANA registry</a> is the authority for registered names. The receiving endpoint\'s contract still determines which types it accepts.'),
h('1. Content-Type, Accept and Content-Encoding'),p('Content-Type describes the body attached to the message. A request\'s Accept header expresses preferences for the response format. Content-Encoding describes a transformation such as gzip compression. These fields have different jobs:'),c('POST /orders HTTP/1.1\nHost: api.example.com\nContent-Type: application/json\nAccept: application/json\n\n{"sku":"BOOK-7","quantity":2}'),p('An unsupported input representation can produce 415. A server unable to satisfy response-format negotiation may return 406 under its policy. Setting Accept to JSON does not convert an XML request body into JSON.'),
h('2. Text and Structured Data'),p('Use the type that matches the actual representation. A JSON object, newline-delimited records and a JSON text sequence have different framing, even though each can contain JSON values.'),t(['Content','Common media type','Note'],[['JSON','application/json','One JSON value; UTF-8 for interoperable exchange'],['Problem Details JSON','application/problem+json','Structured HTTP error representation'],['XML','application/xml','XML document; follow the format\'s encoding rules'],['CSV','text/csv','Document columns, delimiter and character encoding'],['Plain text','text/plain','Use a charset when needed, commonly UTF-8'],['HTML','text/html','HTML document, not a JSON API response'],['JSON Lines / NDJSON','application/x-ndjson','Widely used convention; check the endpoint contract'],['JSON text sequences','application/json-seq','RFC 7464 record-separator framing'],['Server-sent events','text/event-stream','An event stream with its own line-based syntax']]),p('For JSON, RFC 8259 defines no charset parameter for application/json. Use UTF-8 instead of depending on a charset parameter to change a recipient\'s JSON decoding. For text types, a value such as <em>text/plain; charset=utf-8</em> can identify the encoding explicitly.'),p('Do not label ordinary newline-delimited JSON as application/json-seq. JSON text sequences prefix each record with an ASCII record separator; a newline alone is not equivalent. Document streaming boundaries so clients know when one value is complete.'),
h('3. Binary Files and Downloads'),p('Choose a specific type when the file format is known. <em>application/octet-stream</em> is a generic binary type, not a synonym for every download:'),t(['File content','Media type'],[['PDF','application/pdf'],['ZIP archive','application/zip'],['Gzip data','application/gzip'],['PNG image','image/png'],['JPEG image','image/jpeg'],['WebP image','image/webp'],['SVG image','image/svg+xml'],['Unknown binary content','application/octet-stream']]),p('A compressed HTTP representation is different from a gzip file. A JSON response transferred with gzip can retain application/json as its Content-Type and carry <em>Content-Encoding: gzip</em>. A downloadable .gz file can instead have application/gzip as its representation type.'),p('Use Content-Disposition when you want to suggest a download filename. Media type and disposition are separate decisions. Validate uploaded file content and enforce size limits; trusting the client\'s filename or declared type is not sufficient validation.'),
h('4. Forms and Multipart Requests'),p('Form encoding determines how fields and files are packaged. Choose it based on the API\'s request schema rather than the tool used to send it.'),t(['Format','Media type','Typical use'],[['URL-encoded form','application/x-www-form-urlencoded','Simple name/value fields'],['Multipart form','multipart/form-data; boundary=...','Fields and file parts'],['JSON','application/json','Structured objects and arrays']]),p('A multipart boundary separates parts, and the value in the header must match the body. Let a browser FormData implementation or curl -F generate it. Manually setting multipart/form-data without the matching boundary is a common source of parsing failures.'),
h('5. Vendor Types and the +json Suffix'),p('A structured syntax suffix describes a reusable underlying syntax. For example, application/problem+json uses JSON syntax while assigning particular meaning to its members. A type ending in +json does not mean it has exactly the same schema as every other JSON type.'),p('An API might define a vendor representation such as <em>application/vnd.example.order+json</em>. Document its schema and negotiate it deliberately. Do not assume that every framework configured only for application/json automatically accepts all +json inputs; verify the parser and mapping policy.'),
h('6. Set and Inspect the Header'),p('For a JSON request, send the matching bytes and inspect what comes back. This example uses curl\'s JSON option:'),c('curl -i --json \'{"sku":"BOOK-7","quantity":2}\' https://api.example.com/orders','bash'),p('To inspect the response to a read without mixing headers into a later JSON-processing step, save headers and body separately:'),c('curl --dump-header headers.txt --output body.json https://api.example.com/orders/7','bash'),p('Check that the body parses according to the returned type. A server returning an HTML login page under application/json is inconsistent even if the HTTP status is 200. A client should handle empty-body responses such as 204 without trying to parse JSON.'),
h('7. Conclusion'),p('Choose Content-Type from the representation, not the extension or client tool. Keep format, encoding and download disposition separate, and document any streaming or vendor-specific conventions.'),h('8. References'),refs([('IANA media types','https://www.iana.org/assignments/media-types/'),('MDN common media types','https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/MIME_types/Common_types'),('RFC 8259: JSON','https://www.rfc-editor.org/rfc/rfc8259.html'),('RFC 6839: structured suffixes','https://www.rfc-editor.org/rfc/rfc6839.html'),('RFC 7464: JSON text sequences','https://www.rfc-editor.org/rfc/rfc7464.html')])],
'Common MIME Types for APIs: Content-Type Cheat Sheet','Find Content-Type values for JSON, XML, CSV, files, multipart forms and streams. Understand +json, octet-stream, charset and Content-Encoding.','A practical MIME type reference for API bodies, downloads and forms, with JSON, CSV, binary types, multipart boundaries and structured syntax suffixes.','mime types list')
save('3056',[
p('Choose a Postman alternative by the workflow you need to preserve: local collections, Git review, browser access, automated runs or team collaboration. A client that sends one request well may still lack the scripting or sharing features your collection depends on.'),p('The comparison below covers Bruno, Hoppscotch, Insomnia, Yaak and terminal tools. Product features and plan boundaries were checked against official documentation in October 2026. Evaluate the current edition before migrating; no single client is the best choice for every team.'),
h('1. Compare the Workflow Before the Feature Count'),p('An API collection is a saved group of requests, variables and often tests. Before replacing a tool, list what your collection actually uses: authentication, token refresh, pre-request scripts, assertions, certificates, proxies, shared environments and CI execution. A successful import does not prove those behaviors survived.'),t(['Tool','Useful starting point','Check before adopting'],[['Bruno','Collections alongside source code and Git review','Import fidelity, script compatibility and CLI feature coverage'],['Hoppscotch','Browser access, desktop clients or a self-hosted workflow','Browser networking, interceptor setup and hosting responsibilities'],['Insomnia','Desktop requests with local, Git or cloud storage options','Chosen storage mode, migration behavior and automation'],['Yaak','Local request collections and Git-based collaboration','Required protocol support, imports, plugins and team workflow'],['curl / HTTPie CLI','Reproducible terminal requests and scripts','How collections, secrets, assertions and reports will be managed']]),p('This is a shortlist by fit, not a benchmark ranking. Account requirements, enterprise controls and paid features can change independently of basic request sending.'),
h('2. Bruno: Collections in a Code-Review Workflow'),p('<a href="https://docs.usebruno.com/">Bruno</a> documents request collections, variables, authentication, scripts, tests and a CLI for terminal runs. It is a useful candidate when requests should live near application source and be reviewed through ordinary Git changes.'),p('Try a collection with a development environment, one authenticated request and a dependent request that uses the first response. Inspect the files created by import and a small edit. Decide whether the resulting diff is understandable to a teammate. Keep secret values out of the committed collection, including generated examples and exported environments.'),
h('3. Hoppscotch: Web, Desktop and Self-Hosted Choices'),p('<a href="https://docs.hoppscotch.io/">Hoppscotch</a> provides several clients and documents collections, environments, scripts and collection execution. It is worth evaluating when quick browser access matters or when the team wants to run its own deployment.'),p('A browser client is subject to browser networking rules, including CORS, the policy controlling access to cross-origin responses. A request working in a desktop client may fail directly in a browser. An interceptor, agent or proxy can change the network path; understand which component receives credentials and reaches the API.'),p('Self-hosting gives operational control but also creates work: upgrades, access management, backups and availability. It is not automatically simpler than a desktop application.'),
h('4. Insomnia: Choose the Storage Mode Deliberately'),p('<a href="https://developer.konghq.com/insomnia/storage/">Insomnia</a> documents local and synchronized project-storage options. Its <a href="https://developer.konghq.com/insomnia/git-sync/">Git Sync</a> workflow stores project resources in your repository and uses the repository\'s collaboration controls.'),p('Evaluate the mode your team will actually use rather than repeating outdated claims that every project must be cloud-hosted. Check how environments and secrets are stored, how changes merge, and what account or organization configuration your workflow requires. A local project can still send HTTP traffic to a remote API; local storage describes the collection, not the destination of requests.'),
h('5. Yaak: A Local Collection with Git Collaboration'),p('<a href="https://yaak.app/">Yaak</a> describes a local-first client with request collections, multiple protocols and Git workflows. It is a candidate for developers who want a desktop request workspace and repository-based sharing.'),p('Run a representative migration rather than relying on a protocol checklist. Check OAuth, client certificates, custom proxy settings and any imported scripts your project uses. Review plugin permissions and request templates too: extensions can affect which local data is read or sent.'),
h('6. curl and HTTPie for Terminal Work'),p('curl is a strong baseline for reproducing an HTTP call in a bug report or build script. HTTPie provides an alternative terminal interface with JSON-oriented request syntax. Both require a deliberate approach to saved requests and assertions; a command printing a response is not yet a test suite.'),p('For a tiny smoke check, a shell script may be easier to review than a large collection. For complex token flows and many dependent requests, a collection runner or test framework may be more maintainable. See the <a href="https://restfulapi.net/http-methods/">HTTP methods reference</a> for the semantics that apply regardless of client.'),
h('7. Test a Migration with One Small Collection'),p('Start with one harmless GET, one test-only write, a failing authentication case and an assertion on the response body. Compare method, URL, query encoding, headers and serialized body before comparing screenshots. Then run the collection on a clean machine or CI runner with secrets supplied through its approved secret store.'),p('Also check redirects and TLS verification. A migration that works only after disabling certificate checks or removing assertions has not preserved the original behavior. Record differences in timeout settings, retry defaults, cookie handling and environment precedence.'),p('Export only the data required for migration. Review exported files for tokens and personal data before committing or importing them into a shared service. Treat imported scripts as executable code and inspect them before running.'),
h('8. Which One Should You Try First?'),p('Try Bruno or Yaak when local files and Git review are central. Try Hoppscotch when web access or a self-hosted client is the main requirement. Evaluate Insomnia when its desktop and storage choices fit the team. Keep curl as a small reproducible baseline even if another client manages the full collection.'),p('Retain Postman if the replacement does not meet an essential workflow. The goal is a reliable, understandable way to develop and test the API, not migration for its own sake.'),h('9. References'),refs([('Bruno documentation','https://docs.usebruno.com/'),('Hoppscotch documentation','https://docs.hoppscotch.io/'),('Insomnia storage','https://developer.konghq.com/insomnia/storage/'),('Insomnia Git Sync','https://developer.konghq.com/insomnia/git-sync/'),('Yaak','https://yaak.app/'),('HTTPie CLI','https://httpie.io/docs/cli'),('curl manual','https://curl.se/docs/manpage.html')])],
'Postman Alternatives: Bruno, Hoppscotch, Insomnia and Yaak','Compare Postman alternatives by local storage, Git workflow, browser access and automation. Includes Bruno, Hoppscotch, Insomnia, Yaak and CLI tools.','Choose an API client by workflow: compare local and Git-friendly tools, web clients and terminal options, then test imports, secrets and CI behavior.','postman alternatives')

save('2990',[
p('Use a fake REST API to practice requests without building a backend first. Choose a fixture API for predictable JSON, an echo service to inspect what you sent, or a persistent sandbox when tests must create data and read it back.'),p('Those are different jobs. A service returning a created-looking object after POST may be simulating the write, so the object may not exist on the next GET. Check persistence, authentication and current usage limits before building a test around the service.'),
h('1. Pick a Service by the Skill You Want to Practice'),p('These options were checked against official documentation in October 2026. Free access and quotas can change; no hosted public endpoint should be a dependency for a deterministic unit test.'),t(['Service','Good for','Important limit'],[['JSONPlaceholder','Reading related users, posts and comments; basic request practice','Treat its fake writes as simulations, not durable application storage'],['DummyJSON','Product search, pagination and demo authentication','Product writes are simulated rather than persisted'],['httpbin','Inspecting methods, headers, forms and request bodies','An inspection service, not a product database'],['ReqRes','Project data, API-key access and user-session testing','Current docs require x-api-key; plan and project setup apply'],['Open-Meteo','A read-only project using real weather data','Follow its usage, licensing and commercial-access terms']]),
h('2. JSONPlaceholder for Basic REST Calls'),p('<a href="https://jsonplaceholder.typicode.com/">JSONPlaceholder</a> provides a small set of familiar resources for experimenting with HTTP clients. Read a known post first, then inspect the returned Content-Type and JSON fields:'),c('curl -i https://jsonplaceholder.typicode.com/posts/1','bash'),p('Use this to learn request construction, status checks and object parsing. For a frontend demo, map the response to the UI model rather than assuming every real API will use the same field names or pagination style.'),p('Treat a fake POST response as a request/response exercise. Do not infer persistence from a returned identifier. A create-then-read integration test needs an API with an explicit persistence guarantee or a local test backend.'),
h('3. DummyJSON for Search and Pagination'),p('<a href="https://dummyjson.com/docs/products">DummyJSON</a> supplies product-shaped data and query options suitable for practicing a list UI. This request asks for a small page:'),c('curl "https://dummyjson.com/products?limit=2&skip=0"','bash'),p('Inspect the wrapper object and its products array rather than treating every API response as a bare array. Exercise an empty result, a later page and a small limit. Do not hard-code the entire current catalog into assertions.'),p('The documentation explicitly says product additions, updates and deletions are simulated. That makes them useful for learning the response shape, but unsuitable for proving durable state changes. Demo login credentials and tokens also do not establish that your own authorization design is correct.'),
h('4. httpbin for Inspecting the Request'),p('<a href="https://httpbin.org/">httpbin</a> echoes request details and exposes endpoints for HTTP behavior. Use synthetic values to see how the client serializes a header, query, form or JSON body:'),c('curl --json \'{"message":"hello"}\' https://httpbin.org/post','bash'),p('Inspect the echoed content type and parsed JSON. A response from an echo service confirms what reached that service; it does not test an orders API\'s validation or business rules. Never send production tokens, private files or customer data to a public inspection endpoint.'),p('Hosted inspection services can be busy or temporarily unavailable. If a learning exercise fails, distinguish a service outage from a malformed request before changing the code.'),
h('5. ReqRes for API Keys and Project Data'),p('<a href="https://reqres.in/docs">ReqRes</a> now documents API-key access using <em>x-api-key</em>. Create a project and use the key and endpoint from its dashboard. Older examples that assume every request is anonymous may fail.'),p('The current documentation distinguishes manage keys used for setup from public keys intended for read-only testing, and describes session tokens for per-user access. Follow the permission model rather than putting a manage key into a browser application.'),p('Check the free plan and persistence policy for your project before writing a suite that depends on it. Create test-owned records, identify them unambiguously and remove them according to the sandbox\'s supported workflow. Shared state and parallel runs can otherwise interfere with each other.'),
h('6. Public Data for a Small Project'),p('A real public-data API is useful when the goal is building an application rather than learning CRUD behavior. <a href="https://open-meteo.com/en/docs">Open-Meteo</a>, for example, provides weather queries by location and variables:'),c('curl "https://api.open-meteo.com/v1/forecast?latitude=52.52&longitude=13.41&current=temperature_2m"','bash'),p('Check units, timestamps, timezone and missing-value behavior. Weather values change, so assert structure and plausible constraints rather than one exact temperature. Follow the service\'s licensing, attribution, usage and commercial-access conditions; public accessibility is not unrestricted permission.'),
h('7. Turn Practice into Reliable Tests'),p('For a hosted smoke check, assert the HTTP status, content type and a few documented fields. Use a timeout and a small request volume. Avoid making availability of an unrelated free service decide whether your own unit tests pass.'),p('For repeatable tests, capture a small permitted fixture or run a local stub. Make the stub return controlled cases: success, empty data, invalid JSON, authentication failure, a rate limit and a timeout. A fixture tests your parsing and UI logic; a scheduled external smoke check tests whether an integration still works. Keep those purposes separate.'),p('For write tests, verify whether writes persist before asserting read-after-write behavior. Isolate data per run and test cleanup failures too. The <a href="https://restfulapi.net/rest-api-testing/">REST API testing guide</a> covers broader test design.'),
h('8. Conclusion'),p('Choose a fake API by the behavior you need: fixtures, inspection, authentication or persistent state. Read the service contract, use synthetic data and move deterministic automated tests onto controlled inputs.'),h('9. References'),refs([('JSONPlaceholder','https://jsonplaceholder.typicode.com/'),('DummyJSON products','https://dummyjson.com/docs/products'),('httpbin','https://httpbin.org/'),('ReqRes documentation','https://reqres.in/docs'),('Open-Meteo documentation','https://open-meteo.com/en/docs')])],
'Free Fake REST APIs for Testing and Practice','Find fake REST APIs for JSON fixtures, pagination, request inspection and auth practice. Compare JSONPlaceholder, DummyJSON, httpbin, ReqRes and public data.','Choose a practice API by behavior: predictable JSON, request inspection, authentication or persistent state. Learn which fake writes are only simulated.','free apis for testing')
raw=(R/'originals/3075.wp.html').read_text(encoding='utf-8')
changes={
'A free LLM API is a hosted large language model that we can call over HTTP without paying, through a provider\'s free tier with daily rate limits, or an open model that we run on our own machine behind an OpenAI-compatible endpoint.':'A free LLM API provides a no-charge allowance for calling a hosted large language model over HTTP. A local model is another option: it avoids hosted per-token charges, but uses your own hardware and electricity.',
'As of October 10, 2026':'As checked on October 22, 2026',
'Google Gemini API, Groq, OpenRouter <em>:free</em> models, Mistral, Cloudflare Workers AI':'Google Gemini API, Groq, OpenRouter <em>:free</em> models, Cloudflare Workers AI',
'A daily or per-minute allowance that resets and never ends':'An allowance that resets while the provider continues offering that tier',
'<td>Trial credits</td><td>Cohere, NVIDIA, Cerebras</td><td>A one-time balance or a trial key for testing</td>':'<td>Evaluation access or trial credits</td><td>Cohere, NVIDIA, Cerebras</td><td>Testing access with provider-specific usage limits or expiring credits</td>',
'Any open model on our own hardware, with no rate limit and no data leaving the machine':'A supported model under its license, using our own compute; privacy depends on local-only execution',
'Notice that the same code works for every provider in this article, and Cloudflare\'s base URL also contains the account ID.':'This basic Chat Completions pattern works with providers that implement the required subset. Cloudflare\'s base URL also contains the account ID. Test each provider\'s supported models and parameters rather than assuming full compatibility.',
'A free tier renews every minute and every day and never ends. Trial credits are a one-time balance that runs out or expires. A paid-only API needs a prepaid balance before the first call.':'A renewing tier resets its allowance on the provider\'s schedule, but the offer can change or end. Evaluation keys can have recurring limits while still being restricted to testing. Trial credits are a balance that runs out or expires. Paid API access follows the provider\'s billing arrangements.',
'The limits come from each provider\'s documentation on October 10, 2026.':'The offers were checked against provider documentation on October 22, 2026. Limits are model- and account-dependent; confirm the allowance in your console before relying on a number.',
'Not retained by default</a>':'Not retained by default for ordinary inference; feature and reliability exceptions apply</a>',
'Private data, offline work, no rate limits':'Private data and offline work with local-only execution',
'The model runs on our machine, nothing leaves it':'Inference runs on our machine when the model, tools and configuration remain local',
'The provider answers <a href="https://restfulapi.net/http-status-429-too-many-requests/">HTTP 429 Too Many Requests</a>.':'A provider often answers <a href="https://restfulapi.net/http-status-429-too-many-requests/">HTTP 429 Too Many Requests</a>, but exhausted credits or account restrictions can use other errors. Read the provider\'s error code as well as the HTTP status.',
'A short retry-after means wait and retry, a long one means switch providers.':'The example waits only when Retry-After fits its budget; a long delay defers the call or moves to another approved provider. The delay alone does not prove which quota was exhausted.',
'Yes. Ollama and LM Studio download open models and serve them behind an OpenAI-compatible endpoint on our own machine. There is no rate limit and no per-token cost, and prompts never leave the machine. The cost is hardware, since a small model with a few billion parameters runs on a laptop, while larger models need a GPU with enough memory.':'Ollama and LM Studio can serve downloaded models through a local OpenAI-compatible endpoint. Local inference avoids a hosted request quota, but remains limited by memory, compute and concurrency. Use a local model under its license and check that cloud routing, tools and telemetry do not send data elsewhere. Merely using a localhost base URL is not a complete privacy guarantee.',
'Local models are also the right choice for automated tests, because a test suite that calls a hosted free tier fails on the day the quota runs out.':'A local stub is useful for deterministic transport and error-handling tests. Local models can support separate behavior evaluations, while hosted integration checks should be isolated from tests that must run without network access or quota.',
'only after adding a payment method.':'only after adding a verified payment method.',
'A trial is useful for a one-week test, not for a project that runs for months.':'Check duration and permitted use before treating evaluation access as a recurring production allowance.',
'The x':'The x'
}
for a,b in changes.items():
 if a==b:continue
 assert a in raw,a
 raw=raw.replace(a,b)
# Remove the Mistral row from the renewing-tier list: current plan access must be checked in the account.
raw=re.sub(r'<tr><td>Mistral</td>.*?</tr>','',raw,flags=re.S)
raw=raw.replace('<p>Gemini counts limits per Google Cloud project', '<p>Mistral access is plan-dependent; check its current <a href="https://docs.mistral.ai/admin/billing-usage/subscriptions" target="_blank" rel="noopener">subscription</a> and API Limits pages rather than assuming a renewing free API tier.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Gemini counts limits per Google Cloud project')
# Hosted privacy policy and failover are distinct decisions.
anchor='<p>Keep keys in environment variables, never in code.'
raw=raw.replace(anchor,'<p>Before enabling fallback, approve each destination for the data in the prompt. A provider change can alter privacy terms, tool support and output behavior; retrying at another host is not a transparent change.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n'+anchor)
# Explain the deliberately limited retry example without changing the existing snippet.
needle='<p>Token limits often run out before request limits'
raw=raw.replace(needle,'<p>The demo handles numeric Retry-After seconds and otherwise uses a short default. A production client should also parse HTTP-date values, honor valid delays without retrying earlier, and bound total elapsed time. A long hint is a reason to stop waiting within this example\'s budget, not proof of a daily-quota error.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n'+needle)
# Avoid presenting an unverified account offer as a guarantee.
soup=BeautifulSoup(raw,'html.parser')
for row in soup.select('table tr'):
 cells=row.find_all('td',recursive=False)
 if len(cells)==2 and cells[0].get_text(strip=True) in ('OpenAI','Anthropic','DeepSeek'):
  cells[1].clear();cells[1].append('Check the current API pricing and any account-specific evaluation offer. A free chat application plan does not establish free API access.')
raw=str(soup)
# Remove a heuristic decision diagram whose text overstates what Retry-After proves.
soup=BeautifulSoup(raw,'html.parser')
for fig in soup.select('figure.wp-block-image'):
 img=fig.find('img')
 if img and 'free-llm-api-http-429-handling.png' in img.get('src',''):fig.decompose()
raw=str(soup)
# Preserve all existing executable examples.
a=BeautifulSoup((R/'originals/3075.wp.html').read_text(encoding='utf-8'),'html.parser');b=BeautifulSoup(raw,'html.parser')
assert [x.get_text() for x in a.select('pre')]==[x.get_text() for x in b.select('pre')]
(R/'articles/3075.wp.html').write_text(raw,encoding='utf-8')
(R/'3075.diff').write_text(''.join(difflib.unified_diff((R/'originals/3075.wp.html').read_text(encoding='utf-8').splitlines(True),raw.splitlines(True))),encoding='utf-8')
M['3075']=dict(seo_title='Free LLM APIs for Developers: Tiers, Trials and Local Models',description='Compare free LLM API tiers, evaluation credits and local models. Check provider limits, privacy terms, OpenAI compatibility and safe quota handling.',excerpt='Compare renewing LLM allowances, evaluation access and local inference. Learn how limits, privacy, compatibility and fallback affect a free API prototype.',keyphrase='free llm api')
(R/'metadata.json').write_text(json.dumps(M,indent=2),encoding='utf-8')
for id in M:
 doc=BeautifulSoup((R/'articles'/f'{id}.wp.html').read_text(encoding='utf-8'),'html.parser')
 assert 'PLANNING NOTE' not in doc.get_text() and not doc.select('.toc')
 print(id,len(doc.get_text(' ',strip=True).split()),'words')

# Protect copyable options from WordPress smart typography.
for file in (R/'articles').glob('*.html'):
    body=file.read_text(encoding='utf-8')
    body=re.sub(r'<em>([^<>]*--[^<>]*)</em>',lambda m:'<em><code>'+m.group(1)+'</code></em>',body)
    body=body.replace('<em>["Ada", "Sam"]</em>','<code>["Ada", "Sam"]</code>')
    file.write_text(body,encoding='utf-8')
